impl ClientProfile {
    /// Disable Midnight secrets on the four official Classic profiles.
    /// Forever retains its separate existing compatibility policy.
    pub const fn uses_secret_values(self) -> bool {
        match self {
            Self::Retail | Self::Ptr | Self::WowForever => true,
            Self::Wrath | Self::Mists | Self::Era | Self::Anniversary => false,
        }
    }

    /// Forever Classic identity is an inferred cached-addon compatibility policy,
    /// not a native-client measurement. Preserve other profiles' existing values.
    pub const fn current_expansion_level(self) -> i32 {
        match self {
            Self::WowForever => 0,
            _ => 11,
        }
    }

    /// Keep the legacy API's existing default outside the modeled Forever scope.
    pub const fn expansion_level(self) -> i32 {
        match self {
            Self::WowForever => self.current_expansion_level(),
            _ => 10,
        }
    }

    pub fn subdir(self) -> &'static str {
        match self {
            ClientProfile::Retail => "Retail",
            ClientProfile::Ptr => "Ptr",
            ClientProfile::Wrath => "Wrath",
            ClientProfile::Mists => "Mists",
            ClientProfile::Era => "Era",
            ClientProfile::Anniversary => "Anniversary",
            ClientProfile::WowForever => "WowForever",
        }
    }

    pub fn cache_subdir(self) -> &'static str {
        match self {
            ClientProfile::Retail => "retail",
            ClientProfile::Ptr => "ptr",
            ClientProfile::Wrath => "wrath",
            ClientProfile::Mists => "mists",
            ClientProfile::Era => "era",
            ClientProfile::Anniversary => "anniversary",
            ClientProfile::WowForever => "wowforever",
        }
    }

    pub const fn interface_version(self) -> u32 {
        match self {
            ClientProfile::Retail | ClientProfile::Ptr => RETAIL_API_INTERFACE_VERSION,
            ClientProfile::Wrath => 38001,
            ClientProfile::Mists => 50504,
            ClientProfile::Era | ClientProfile::Anniversary => 11507,
            ClientProfile::WowForever => 16001,
        }
    }
}

